<script setup lang="ts">
import {statusLabels,money,type CustomerRequestDetail} from '@ellas/shared';
definePageMeta({middleware:'customer'});useHead({title:'Detalle de mi pedido'});
const route=useRoute();const request=useRequestFetch();
const {data:order,error}=await useAsyncData(`customer-order-${String(route.params.id)}`,()=>request<CustomerRequestDetail>(`/api/customer/requests/${encodeURIComponent(String(route.params.id))}`));
</script>
<template><div class="container customer-page"><NuxtLink to="/mi-cuenta" class="text-link"><AppIcon name="ArrowLeft" :size="17"/> Mis pedidos</NuxtLink><div v-if="error||!order" class="customer-empty"><h1>Pedido no disponible.</h1><p>No se ha encontrado una solicitud vinculada a tu cuenta.</p><NuxtLink to="/mi-cuenta" class="button dark">Volver a mis pedidos</NuxtLink></div><template v-else><header class="customer-heading"><div><span class="eyebrow">{{order.type==='pedido'?'TU PEDIDO':'TU PRESUPUESTO'}}</span><h1 class="customer-number">{{order.number}}</h1><p>{{order.quantity}} prendas para tu equipo.</p></div><span class="status-badge">{{statusLabels[order.status]}}</span></header><p v-if="order.demo" class="alert">Ejemplo ficticio de demostración.</p><div class="customer-detail"><section class="customer-card"><h2>Tus prendas</h2><article v-for="line in order.lines" :key="`${line.reference}:${line.color}:${line.size}`" class="customer-line"><img :src="line.image" :alt="line.name" width="62" height="78"/><div><small>{{line.reference}}</small><h3>{{line.name}}</h3><p>{{line.colorName}} · Talla {{line.size}}</p></div><strong>{{line.quantity}} <span>uds.</span></strong></article></section><aside><section v-if="order.proposal" class="customer-card"><h2>Tu propuesta</h2><p>Total con impuestos</p><strong class="customer-price">{{money(order.proposal.totalCents)}}</strong><p v-if="order.proposal.notes" class="customer-preserve">{{order.proposal.notes}}</p><p class="fine-print">Consulta con la tienda para confirmar precio, disponibilidad y plazos.</p></section><section class="customer-card"><h2>Detalles de la solicitud</h2><p v-if="order.desiredDate">Fecha deseada: {{order.desiredDate}}</p><p>Personalización: {{order.personalization.enabled?'Sí':'No'}}</p><p v-if="order.personalization.enabled">{{order.personalization.placement}}</p><p v-if="order.personalization.notes" class="customer-preserve">{{order.personalization.notes}}</p><a v-if="order.personalization.uploadId" :href="`/api/uploads/${order.personalization.uploadId}`" target="_blank" rel="noopener" class="text-link">Ver mi logo <AppIcon name="ExternalLink" :size="16"/></a><p v-if="order.notes" class="customer-preserve">{{order.notes}}</p><p v-if="!order.proposal" class="fine-print">Precio bajo presupuesto. El equipo confirmará tu solicitud.</p></section><section class="customer-card"><h2>Contacto</h2><p>{{order.contact.name}}</p><p>{{order.contact.email}}</p><p>{{order.contact.phone}}</p><p v-if="order.contact.company">{{order.contact.company}}</p></section></aside></div></template></div></template>
